svg.script:

(function() {
  'use strict';

  // Variables globales
  const SVG_NS = 'http://www.w3.org/2000/svg';
  let currentSection = 'inicio';

  // Utilidades
  const $ = {
    qs: selector => document.querySelector(selector),
    qsa: selector => document.querySelectorAll(selector),
    create: (tag, attrs = {}) => {
      const el = document.createElementNS(SVG_NS, tag);
      Object.entries(attrs).forEach(([key, value]) => el.setAttribute(key, value));
      return el;
    }
  };

  // Manejo de navegación
  const Navigation = {
    init() {
      const navLinks = $.qsa('.nav-link');
      navLinks.forEach(link => {
        link.addEventListener('click', this.handleNavClick.bind(this));
        link.style.cursor = 'pointer';
      });
    },

    handleNavClick(e) {
      const target = e.target.getAttribute('data-target');
      this.setActiveSection(target);
      this.triggerCanvasAction('navigate', { section: target });
    },

    setActiveSection(section) {
      // Remover active de todos
      $.qsa('.nav-link').forEach(link => {
        link.setAttribute('fill', '#b8b8b8');
        link.classList.remove('active');
      });

      // Activar el seleccionado
      const activeLink = $.qs(`[data-target="${section}"]`);
      if (activeLink) {
        activeLink.setAttribute('fill', '#ffffff');
        activeLink.classList.add('active');
        currentSection = section;
      }

      // Actualizar indicador
      this.updateIndicator(section);
    },

    updateIndicator(section) {
      const indicators = $.qsa('line[stroke="#4ecdc4"]');
      indicators.forEach(line => line.remove());

      const activeLink = $.qs(`[data-target="${section}"]`);
      if (activeLink) {
        const x = parseFloat(activeLink.getAttribute('x'));
        const line = $.create('line', {
          x1: x + 5, y1: 58, x2: x + 25, y2: 58,
          stroke: '#4ecdc4', 'stroke-width': 2, 'stroke-linecap': 'round'
        });
        activeLink.parentNode.appendChild(line);
      }
    }
  };

  // Manejo de botones CTA
  const CTAButtons = {
    init() {
      const buttons = $.qsa('.btn-primary, .btn-secondary');
      buttons.forEach(btn => {
        btn.addEventListener('click', this.handleClick.bind(this));
        btn.style.cursor = 'pointer';
        this.addHoverEffects(btn);
      });
    },

    handleClick(e) {
      const button = e.currentTarget;
      const text = button.querySelector('text').textContent;

      if (text === 'Explora Ahora') {
        this.showToast('¡Explorando guitarras personalizadas!');
        this.triggerCanvasAction('explore_guitars');
      }
    },

    addHoverEffects(button) {
      const rect = button.querySelector('rect');
      const originalFill = rect.getAttribute('fill');
      const originalStroke = rect.getAttribute('stroke');

      button.addEventListener('mouseenter', () => {
        if (button.classList.contains('btn-primary')) {
          rect.setAttribute('fill', '#45b7b8');
          button.style.transform = 'translateY(-2px)';
        } else {
          rect.setAttribute('fill', '#4ecdc4');
          button.querySelector('text').setAttribute('fill', '#1a1a2e');
        }
      });

      button.addEventListener('mouseleave', () => {
        rect.setAttribute('fill', originalFill);
        if (originalStroke) rect.setAttribute('stroke', originalStroke);
        button.style.transform = 'translateY(0)';
        if (button.classList.contains('btn-secondary')) {
          button.querySelector('text').setAttribute('fill', '#4ecdc4');
        }
      });
    },

    showToast(message) {
      const toast = $.qs('#toastNotification');
      const text = $.qs('#toastText');

      text.textContent = message;

      // Animación de entrada
      toast.style.transition = 'all 0.3s ease';
      toast.setAttribute('opacity', '1');
      toast.setAttribute('transform', 'translate(900, 120)');

      // Auto-hide después de 3 segundos
      setTimeout(() => {
        toast.setAttribute('opacity', '0');
        toast.setAttribute('transform', 'translate(1200, 120)');
      }, 3000);
    },

    triggerCanvasAction(action, data = {}) {
      console.log('Canvas Action:', action, data);

      // PostMessage para Canvas Apps
      if (window.parent && window.parent.postMessage) {
        window.parent.postMessage({
          type: 'CANVAS_ACTION',
          action: action,
          data: data,
          timestamp: new Date().toISOString(),
          source: 'guitar-luthier-svg'
        }, '*');
      }

      // Almacenar en localStorage
      try {
        localStorage.setItem('lastAction', JSON.stringify({
          action: action,
          data: data,
          timestamp: new Date().toISOString()
        }));
      } catch (e) {
        console.warn('localStorage not available:', e);
      }
    }
  };

  // Efectos de hover para elementos
  const HoverEffects = {
    init() {
      // Logo hover
      const logo = $.qs('.logo');
      if (logo) {
        logo.style.cursor = 'pointer';
        logo.addEventListener('mouseenter', () => logo.setAttribute('fill', '#4ecdc4'));
        logo.addEventListener('mouseleave', () => logo.setAttribute('fill', '#ffffff'));
      }

      // Hero image hover
      const heroImage = $.qs('#heroImage rect');
      if (heroImage) {
        heroImage.style.cursor = 'pointer';
        heroImage.addEventListener('mouseenter', () => {
          heroImage.style.transform = 'scale(1.05)';
          heroImage.style.transition = 'transform 0.6s ease';
        });
        heroImage.addEventListener('mouseleave', () => {
          heroImage.style.transform = 'scale(1)';
        });
      }
    }
  };

  // Integración con Canvas Apps
  const CanvasIntegration = {
    init() {
      // Escuchar mensajes de Canvas
      window.addEventListener('message', this.handleCanvasMessage.bind(this));

      // Notificar que el SVG está listo
      if (window.parent && window.parent.postMessage) {
        window.parent.postMessage({
          type: 'SVG_READY',
          timestamp: new Date().toISOString(),
          capabilities: [
            'navigation',
            'cta-actions',
            'hover-effects',
            'responsive-design',
            'postmessage-api'
          ]
        }, '*');
      }
    },

    handleCanvasMessage(event) {
      const { data } = event;

      if (data.type === 'CANVAS_COMMAND') {
        switch (data.command) {
          case 'UPDATE_CONTENT':
            this.updateContent(data.payload);
            break;
          case 'TRIGGER_ACTION':
            CTAButtons.triggerCanvasAction(data.payload.action, data.payload.data);
            break;
          case 'SET_SECTION':
            Navigation.setActiveSection(data.payload.section);
            break;
        }
      }
    },

    updateContent(payload) {
      if (payload.title) {
        const titleElement = $.qs('.hero-title');
        if (titleElement) {
          // Actualizar título con múltiples líneas
          const lines = payload.title.split(' ');
          const tspans = titleElement.querySelectorAll('tspan');
          tspans.forEach((tspan, index) => {
            if (lines[index]) tspan.textContent = lines[index];
          });
        }
      }

      if (payload.description) {
        const descElement = $.qs('.hero-description');
        if (descElement) {
          // Actualizar descripción con múltiples líneas
          const lines = payload.description.match(/.{1,40}(\s|$)/g) || [payload.description];
          const tspans = descElement.querySelectorAll('tspan');
          tspans.forEach((tspan, index) => {
            if (lines[index]) tspan.textContent = lines[index].trim();
          });
        }
      }
    }
  };

  // Animaciones
  const Animations = {
    init() {
      this.addFadeInAnimations();
    },

    addFadeInAnimations() {
      const animatedElements = [
        { selector: '#heroContent rect', delay: 0 },
        { selector: '.hero-title', delay: 0.1 },
        { selector: '.hero-description', delay: 0.2 },
        { selector: '#heroCTA', delay: 0.3 },
        { selector: '#heroImage', delay: 0.4 }
      ];

      animatedElements.forEach(({ selector, delay }) => {
        const element = $.qs(selector);
        if (element) {
          element.style.opacity = '0';
          element.style.transform = 'translateY(30px)';
          element.style.transition = 'all 0.8s ease';

          setTimeout(() => {
            element.style.opacity = '1';
            element.style.transform = 'translateY(0)';
          }, delay * 1000);
        }
      });
    }
  };

  // API Pública para Canvas Apps
  window.GuitarSVGApp = {
    // Obtener datos de la página
    getPageData() {
      return {
        currentSection: currentSection,
        title: $.qs('.hero-title')?.textContent || '',
        description: $.qs('.hero-description')?.textContent || ''
      };
    },

    // Realizar acciones
    performAction(type, data = {}) {
      switch (type) {
        case 'show-notification':
          CTAButtons.showToast(data.message || 'Acción realizada');
          break;
        case 'trigger-cta':
          CTAButtons.triggerCanvasAction(data.action || 'generic_action', data);
          break;
        case 'navigate-to':
          Navigation.setActiveSection(data.section || 'inicio');
          break;
        case 'update-content':
          CanvasIntegration.updateContent(data);
          break;
      }
    },

    // Estado de la aplicación
    getState() {
      return {
        ready: true,
        currentSection: currentSection,
        timestamp: new Date().toISOString()
      };
    }
  };

  // Inicialización
  function init() {
    console.log('🎸 Guitar SVG Canvas Ready');

    Navigation.init();
    CTAButtons.init();
    HoverEffects.init();
    CanvasIntegration.init();
    Animations.init();

    // Marcar como listo
    document.body?.classList?.add('svg-app-ready');
  }

  // Auto-inicialización
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
